#pragma once

// Interactive forms (PLAN.md phase 8e, ISO 32000-2 §12.7): list the fields of the document's AcroForm
// and fill them. Filling sets the field's value (/V) and gives each of its widgets the appearance of
// that value, generated by the engine (§12.7.4.3): text and choice fields in the field's own font when
// it can write the value — a simple font with known widths that has a glyph for every character —,
// otherwise in Helvetica; check boxes and radio buttons by turning on the widget's state (/AS), drawing
// one when the widget has none. So every reader shows the value as Capriole does, whether or not it
// generates appearances itself.
//
// Signature fields (phase 8h), push buttons and read-only fields are listed but not filled. A form that
// also has an XFA form (§12.7.9) is filled in its AcroForm, and the XFA form is removed: readers that
// know XFA would show it instead of the values written here.
//
// Edits mark only the objects they touch (the field, its widgets, their new appearances; the AcroForm
// when XFA goes), so an incremental save appends just those. As for the other edits, a document whose
// structure needed repairs is refused for filling (edit/pages.hpp); listing works on any document.

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

#include "capriole/core/error.hpp"
#include "capriole/document/document.hpp"
#include "capriole/graphics/geometry.hpp"
#include "capriole/model/object.hpp"

namespace capriole::edit {

enum class FieldType : std::uint8_t {
  kText,
  kCheckBox,
  kRadio,
  kPushButton,
  kComboBox,
  kListBox,
  kSignature,
};

struct FieldWidget {
  model::ObjectRef ref;               // the widget annotation (the field itself when they are merged)
  std::optional<std::uint32_t> page;  // index from 0; none when no page lists it
  graphics::Rect rect;                // as shown on its page (edit/annotations.hpp), page space when none
  std::string on_state;               // check boxes and radio buttons: the name of its "on" state
};

struct ChoiceOption {
  std::string value;    // UTF-8: what /V holds when chosen (the export value)
  std::string display;  // UTF-8: what the field shows
};

struct FieldInfo {
  model::ObjectRef ref;  // the terminal field
  std::string name;      // fully qualified (partial names joined with '.'), UTF-8
  std::string label;     // /TU, UTF-8
  FieldType type = FieldType::kText;
  // The value: text and combo boxes one string; list boxes the chosen options (none or several);
  // check boxes and radio buttons the state that is on ("Off" when none).
  std::vector<std::string> value;
  std::vector<ChoiceOption> options;        // combo and list boxes; check boxes and radio buttons: their on states
  std::optional<std::uint32_t> max_length;  // text: /MaxLen
  bool read_only = false;
  bool required = false;
  bool multiline = false;     // text
  bool password = false;      // text
  bool comb = false;          // text: one character per cell, max_length cells
  bool editable = false;      // combo box: any text, not only the options
  bool multi_select = false;  // list box
  bool fillable = false;      // fill_field takes it: not read-only, not a signature, not a push button
  std::vector<FieldWidget> widgets;
};

// The terminal fields of the document's form, in the order of the field tree; empty when it has none, or
// when its catalog cannot be read (the form hangs from it).
[[nodiscard]] Result<std::vector<FieldInfo>> list_fields(Document& document);

// Fills field ref (a terminal field, as list_fields gives it) with value, UTF-8:
// - text: one string (none or empty clears it). Line breaks become spaces in a single-line field;
//   kOutOfRange when longer than /MaxLen.
// - check box: its on state, or "Off" (none or empty: "Off").
// - radio button: the on state of one of its widgets, or "Off"; widgets sharing that state come on
//   together.
// - combo box: one option's value, or any text when editable; list box: option values, one unless
//   multi-select. kOutOfRange for a value that is not an option.
// kUnsupported for a read-only field, a signature, a push button; kOutOfRange for a reference that is not
// a terminal field of the form.
[[nodiscard]] Result<void> fill_field(Document& document, model::ObjectRef ref, const std::vector<std::string>& value);

}  // namespace capriole::edit
